# evaluation_demo.py: Summarization Evaluation Demo (ROUGE Score)
from rouge_score import rouge_scorer

# 1. Define the Human-Written (Reference) Summary
# This is the ideal summary a human expert would write.
reference_summary = (
    "Duplications of the alimentary tract are rare congenital malformations "
    "that primarily affect the GI tract. Diagnosis relies heavily on imaging, "
    "such as CT and MRI scans."
)

# 2. Define the Generated Summary (Your AI's Output)
# This mimics the concise output generated by your LLM pipeline.
generated_summary = (
    "duplications of the alimentary tract are well-known but rare congenital "
    "malformations that can occur anywhere in the GI tract . Diagnosis is mainly "
    "done via imaging like CT and MRI."
)

# 3. Initialize the ROUGE Scorer
# ROUGE-1 (unigram overlap), ROUGE-2 (bigram overlap), and ROUGE-L (longest common subsequence).
scorer = rouge_scorer.RougeScorer(['rouge1', 'rouge2', 'rougeL'], use_stemmer=True)

# 4. Calculate the Scores
scores = scorer.score(
    target=reference_summary, # The target is the human reference summary
    prediction=generated_summary # The prediction is your AI's summary
)

# 5. Display the Formal Evaluation
print("--- Formal Summarization Evaluation (ROUGE Score) ---")
print("ROUGE-1 (Unigram Overlap F-Measure): {:.4f}".format(scores['rouge1'].fmeasure))
print("ROUGE-2 (Bigram Overlap F-Measure): {:.4f}".format(scores['rouge2'].fmeasure))
print("ROUGE-L (Longest Match F-Measure): {:.4f}".format(scores['rougeL'].fmeasure))

print("\nExplanation: These scores measure the content overlap between the AI's summary and the human reference.")